using System;
using System.IO;
using System.Reflection;
using System.Windows.Forms;
namespace BF4Bots { public static class WizardTests {
 public static void Run(string report){var flags=BindingFlags.Instance|BindingFlags.NonPublic;var type=typeof(Central);var advance=type.GetMethod("AdvanceWizard",flags);string root=Path.Combine(Path.GetTempPath(),"BF4-wizard-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);using(var incomplete=new Central(root,false)){bool blocked=false;try{advance.Invoke(incomplete,null);}catch(TargetInvocationException ex){blocked=ex.InnerException is InvalidDataException;}if(!blocked||((ProgressBar)type.GetField("setupProgress",flags).GetValue(incomplete)).Value!=0)throw new Exception("Instalação incompleta avançou.");}File.WriteAllText(Path.Combine(root,"config.txt"),"BlazeIP=192.168.1.12\r\nUserId=JogadorTeste\r\nExtraArguments=\r\n");foreach(var file in new[]{"BF4Launcher.exe","bf4_no_drm.exe"})File.WriteAllText(Path.Combine(root,file),"fixture");using(var form=new Central(root,false)){form.Show();Application.DoEvents();var progress=(ProgressBar)type.GetField("setupProgress",flags).GetValue(form);var start=(Button)type.GetField("start",flags).GetValue(form);for(int i=0;i<5;i++){if(start.Visible||progress.Value!=i*20)throw new Exception("Progresso ou ação final adiantados.");advance.Invoke(form,null);Application.DoEvents();}if(progress.Value!=100||!start.Visible)throw new Exception("Ação final não apareceu em 100%.");System.Threading.Thread.Sleep(550);Application.DoEvents();using(var image=new System.Drawing.Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new System.Drawing.Rectangle(System.Drawing.Point.Empty,form.Size));image.Save(Path.Combine(Path.GetDirectoryName(report),"wizard-finish.png"));}form.Close();}}
}}
